    Mockito.when(endpoint.isEndpointAcquired()).thenReturn(false);
    Mockito.when(endpoint.execute(Mockito.anyString(), Mockito.same(request), Mockito.<HttpClientContext>any())).thenReturn(response);
    Mockito.when(reuseStrategy.keepAlive(Mockito.same(request), Mockito.same(response), Mockito.<HttpClientContext>any())).thenReturn(false);
    final ExecChain.Scope scope = new ExecChain.Scope("test", route, request, endpoint, context);
    final ClassicHttpResponse finalResponse = mainClientExec.execute(request, scope, null);
